import { normalizeReport, assess, freshness, MAX_REPORT_BYTES } from './report.js';
const $ = id => document.getElementById(id);
let activeReport = null;
let isSample = false;
function newCode() { const bytes = new Uint8Array(4); crypto.getRandomValues(bytes); return 'MC-' + Array.from(bytes, b => b.toString(16).padStart(2,'0')).join('').toUpperCase(); }
function updateCommand() { const code = $('challenge').value.trim().toUpperCase(); $('command').textContent = /^[A-Z0-9-]{4,40}$/.test(code) ? `zsh ~/Downloads/mac-check.command ${code}` : 'Enter a check code using letters, numbers and hyphens.'; if (activeReport) render(activeReport,isSample); }
$('challenge').value = newCode(); updateCommand();
$('challenge').addEventListener('input', updateCommand);
$('new-code').addEventListener('click', () => { $('challenge').value = newCode(); updateCommand(); });
$('copy').addEventListener('click', async () => { const code = $('challenge').value.trim().toUpperCase(); if (!/^[A-Z0-9-]{4,40}$/.test(code)) { $('copy-status').textContent = 'Enter a valid check code first.'; return; } try { await navigator.clipboard.writeText($('command').textContent); $('copy-status').textContent = 'Copied. Run this after downloading the script.'; } catch { $('copy-status').textContent = 'Select and copy the command above.'; } });
function textElement(tag, text, className) { const e = document.createElement(tag); e.textContent = text; if (className) e.className = className; return e; }
function render(report, sample = false) {
  activeReport = report; isSample = sample;
  $('report').hidden = false;
  $('report-kind').textContent = sample ? 'SYNTHETIC SAMPLE · NOT A REAL MAC' : 'LOCAL REPORT · SELLER GENERATED';
  $('report-title').textContent = report.hardware.model || report.hardware.modelIdentifier || 'Mac report';
  $('report-badge').textContent = sample ? 'Sample data' : 'Review before sharing';
  const time = Date.parse(report.collectedAt);
  $('report-time').textContent = Number.isFinite(time) ? 'Collected ' + new Date(time).toLocaleString() : 'Collection time unavailable';
  $('report-code').textContent = 'Code: ' + (report.challenge || 'Not provided');
  $('report-serial').textContent = 'Serial ending: ' + (report.hardware.serialEnding || 'Not reported');
  const expected = $('challenge').value.trim().toUpperCase();
  const notes = [sample ? 'This is a synthetic example. It is not evidence about a device.' : '', !sample && report.challenge !== expected ? 'The report code does not match the current check code. Compare it with the code the buyer sent.' : '', !sample ? freshness(report) : '', report.queryErrors.length ? 'Some system queries could not complete. Missing results are not treated as clear.' : ''].filter(Boolean);
  $('matching-note').hidden = !notes.length; $('matching-note').textContent = notes.join(' ');
  const largest = Math.max(0, ...report.storage.map(d => d.sizeBytes || 0));
  const specs = [['Chip', report.hardware.chip || 'Not reported', report.hardware.modelIdentifier], ['Unified memory', report.hardware.memoryGB ? report.hardware.memoryGB + ' GB' : 'Not reported', 'Installed system memory'], ['Physical internal storage', largest ? (largest / 1e9).toFixed(1) + ' GB' : 'Not reported', 'Largest physical disk; capacity before formatting'], ['macOS', report.macOS || 'Not reported', 'Version at collection time']];
  $('spec-grid').replaceChildren(...specs.map(([label, value, detail]) => { const e=textElement('div','','spec'); e.append(textElement('span',label),textElement('strong',value),textElement('small',detail)); return e; }));
  $('checks').replaceChildren(...assess(report).map(c => { const e=textElement('div','','check'); e.append(textElement('span',c.label),textElement('span',c.text,c.kind)); return e; }));
  $('raw-report').textContent = JSON.stringify(report,null,2);
  $('export').disabled = sample;
  $('export-status').textContent = sample ? 'Sample exports are disabled. Load a real report to share.' : 'Ready when you are. Downloading does not upload the report.';
}
async function openFile(file) {
  $('file-error').hidden = true;
  // Clear the previous result before parsing so a failed import cannot export an old report.
  activeReport = null; $('export').disabled = true; $('report').hidden = true;
  $('export-status').textContent = 'Load a valid report to enable export.';
  if (!file) return;
  try { if (file.size > MAX_REPORT_BYTES) throw new Error('That file is larger than 1 MB. Choose the small JSON report generated by Mac Check.'); const report=normalizeReport(JSON.parse(await file.text())); render(report); $('report').scrollIntoView({behavior:'smooth',block:'start'}); }
  catch (error) { $('file-error').hidden=false; $('file-error').textContent = error instanceof SyntaxError ? 'This file is not valid JSON. Choose the report generated by the script.' : error.message || 'Unable to read that report.'; }
}
$('report-file').addEventListener('change', event => openFile(event.target.files[0]));
const zone=document.querySelector('.drop-zone');
zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('dragover'); });
zone.addEventListener('dragleave', () => zone.classList.remove('dragover'));
zone.addEventListener('drop', e => { e.preventDefault(); zone.classList.remove('dragover'); openFile(e.dataTransfer.files[0]); });
$('demo').addEventListener('click', () => { render(normalizeReport({schema:'mac-check/v1',collectedAt:new Date().toISOString(),challenge:'SAMPLE-ONLY',hardware:{model:'Mac mini — example',modelIdentifier:'Mac16,10',chip:'Apple M4',memoryGB:32,serialEnding:'DEMO'},macOS:'26.1',activationLock:'disabled',enrollment:{automated:'no',mdm:'no'},storage:[{device:'disk0',sizeBytes:500277790720,solidState:true}],queryErrors:[]}),true); $('report').scrollIntoView({behavior:'smooth',block:'start'}); });
$('export').addEventListener('click', () => { if (!activeReport || isSample) return; const blob=new Blob([JSON.stringify(activeReport,null,2)+'\n'],{type:'application/json'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download='mac-check-reviewed-'+(activeReport.hardware.serialEnding || 'report')+'.json'; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); $('export-status').textContent='Downloaded. Send the file through your existing seller conversation.'; });
